// Generated by Cypress Author on 2026-10-15.
describe('Kunena forum browsing', () => {
  it('displays the forum categories', () => {
    cy.visit('/index.php?option=com_kunena&view=category&layout=list');

    // The list layout renders the board index: one row (tr#category<id>) per category
    cy.get('tr[id^="category"] h3 a').should('have.length.greaterThan', 0);

    // URLs may be SEF (e.g. /forum/sub1), so compare against the link's own href instead of query params
    cy.get('tr[id^="category"] h3 a')
      .first()
      .should('have.attr', 'href')
      .then((href) => {
        cy.get('tr[id^="category"] h3 a').first().click();
        cy.location('pathname').should('eq', new URL(href, Cypress.config('baseUrl')).pathname);
      });
  });

  it('opens the topic composer for a published category', () => {
    cy.doFrontendLogin();

    cy.task(
      'queryDB',
      'SELECT c.id FROM #__kunena_categories AS c INNER JOIN #__kunena_topics AS t ON t.category_id = c.id WHERE t.hold = 0 AND t.locked = 0 AND c.published = 1 AND c.pubAccess = 1 AND c.locked = 0 ORDER BY t.id ASC LIMIT 1',
    ).then((categories) => {
      expect(categories, 'a published forum category is available').not.to.be.empty;

      cy.visit(`/index.php?option=com_kunena&view=topic&layout=create&catid=${categories[0].id}`);

      cy.get('#postform').should('be.visible');
      cy.get('#postform input[name="subject"]').should('be.visible');
      cy.get('#postform textarea[name="message"]').should('exist');
    });
  });

  it('opens a topic from its category', () => {
    cy.task(
      'queryDB',
      'SELECT t.id, t.category_id, t.subject FROM #__kunena_topics AS t INNER JOIN #__kunena_categories AS c ON c.id = t.category_id WHERE t.hold = 0 AND t.locked = 0 AND c.published = 1 AND c.pubAccess = 1 AND c.locked = 0 ORDER BY t.id ASC LIMIT 1',
    ).then((topics) => {
      expect(topics, 'a published forum topic is available').not.to.be.empty;

      const topic = topics[0];

      cy.visit(`/index.php?option=com_kunena&view=category&catid=${topic.category_id}`);

      // Open whichever topic the category lists first, so the test does not depend on list ordering or paging
      cy.get('#categoryactions .category-item a.topictitle').first().then(($link) => {
        const title = $link.text().trim();

        cy.wrap($link).click();
        cy.get('.kunena-topic-item > h1').should('contain.text', title);
      });

      cy.get('.topic-item-messages').should('be.visible');
      cy.get('.kunena-topic-item nav .pagination').first().should('be.visible')
        .find('.page-item.active .page-link')
        .should('contain.text', '1');
    });
  });

  it('opens the reply composer for a published topic', () => {
    cy.doFrontendLogin();

    cy.task(
      'queryDB',
      'SELECT t.id, t.category_id, t.subject FROM #__kunena_topics AS t INNER JOIN #__kunena_categories AS c ON c.id = t.category_id WHERE t.hold = 0 AND t.locked = 0 AND c.published = 1 AND c.pubAccess = 1 AND c.locked = 0 ORDER BY t.id ASC LIMIT 1',
    ).then((topics) => {
      expect(topics, 'a published forum topic is available').not.to.be.empty;

      const topic = topics[0];

      cy.visit(`/index.php?option=com_kunena&view=topic&layout=reply&catid=${topic.category_id}&id=${topic.id}`);

      cy.get('#postform').should('be.visible');
      cy.get('#postform textarea[name="message"]').should('exist');
      cy.contains('h1', topic.subject).should('be.visible');
    });
  });

  it('searches for a topic by its subject', () => {
    cy.task(
      'queryDB',
      'SELECT t.subject FROM #__kunena_topics AS t INNER JOIN #__kunena_categories AS c ON c.id = t.category_id WHERE t.hold = 0 AND c.published = 1 AND c.pubAccess = 1 ORDER BY t.id ASC LIMIT 1',
    ).then((topics) => {
      expect(topics, 'a published forum topic is available').not.to.be.empty;

      const subject = topics[0].subject;

      cy.visit('/index.php?option=com_kunena&view=search');
      cy.get('#main-search input[name="query"]').type(subject, { parseSpecialCharSequences: false });
      cy.get('#main-search').closest('form').submit();

      // SEF URLs drop view=search, so check the path and the submitted query instead
      cy.location('pathname').should('include', 'search');
      cy.location('search').should('include', 'query=');
      cy.contains(subject).should('be.visible');
    });
  });
});
